    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # dp[i] = max sum of a valid subsequence ending at index i
    dp = [0] * n
    ans = 0
    for i in range(n):
        best = 0
        for j in range(i):
            if a[j] < a[i]:
                if dp[j] > best:
                    best = dp[j]
        dp[i] = best + a[i]
        if dp[i] > ans:
            ans = dp[i]
